function leadCell(value) {
  return ["string", "number", "boolean"].includes(typeof value) ? String(value).trim() : "";
}

function leadHeaders(row) {
  const columns = Object.keys(row).map((name) => [name.trim(), name]);
  if (new Set(columns.map(([name]) => name)).size !== columns.length) {
    throw new Error("The sheet has duplicate column names after trimming spaces");
  }
  return Object.fromEntries(columns);
}

function leadIdentity(row, headers) {
  const timestamp = leadCell(row[headers.Timestamp]);
  const email = leadCell(row[headers["E-Mail"]]).toLowerCase();
  if (!timestamp || !/^[^\s@,<>]+@[^\s@,<>]+\.[^\s@,<>]+$/.test(email)) return null;
  return { timestamp, email, key: JSON.stringify([timestamp, email]) };
}

function leadFromRow(row) {
  const headers = leadHeaders(row);
  const identity = leadIdentity(row, headers);
  const name = leadCell(row[headers["Name Surname"]]);
  if (!identity || !name) throw new Error("A new lead needs Timestamp, E-Mail and Name Surname");
  return {
    ...identity,
    name: name.replace(/[\r\n]+/g, " "),
    phone: leadCell(row[headers.Phone]),
    interest: leadCell(row[headers["Interest Level"]]),
    source: leadCell(row[headers["Lead Source"]]),
    notes: leadCell(row[headers.Notes]),
  };
}

function leadScope(spreadsheetId, sheetId) {
  if (
    typeof spreadsheetId !== "string" ||
    !/^[A-Za-z0-9_-]{12,}$/.test(spreadsheetId) ||
    !Number.isInteger(sheetId) ||
    sheetId < 0
  ) {
    throw new Error("Select a spreadsheet ID and a numeric Google Sheets tab ID");
  }
  return { spreadsheetId, sheetId };
}

function leadSettings(channel, admin, sourceProperty, interestProperty) {
  if (
    typeof channel !== "string" ||
    !/^[CG][A-Z0-9]{8,}$/.test(channel) ||
    typeof admin !== "string" ||
    !/^[^\s@,<>]+@[^\s@,<>]+\.[^\s@,<>]+$/.test(admin) ||
    /\.invalid$/i.test(admin)
  ) {
    throw new Error("Set the Slack channel ID and administrator email before enabling alerts");
  }
  const invalidProperty = (name) =>
    typeof name !== "string" ||
    !/^[a-z][a-z0-9_]{1,50}$/.test(name) ||
    ["email", "phone", "message", "relationshipstatus", "salutation"].includes(name);
  if (
    sourceProperty === interestProperty ||
    invalidProperty(sourceProperty) ||
    invalidProperty(interestProperty)
  ) {
    throw new Error("Configure two different HubSpot custom text properties");
  }
  return { channel, admin, sourceProperty, interestProperty };
}

function uniqueSubmittedLeads(rows) {
  const seen = new Map();
  for (const row of rows) {
    const lead = leadFromRow(row);
    if (seen.has(lead.key))
      throw new Error("More than one incoming row has the same Timestamp and E-Mail");
    seen.set(lead.key, lead);
  }
  return [...seen.values()];
}

function leadMessage(lead, reminder) {
  if (reminder)
    return {
      subject: "Follow-up reminder: " + lead.name,
      body:
        "This hot lead has not been followed up.\n\nName: " +
        lead.name +
        "\nEmail: " +
        lead.email +
        "\nInterest level: " +
        lead.interest +
        "\n\nPlease follow up and update Followed Up? in Google Sheets.",
    };
  return {
    subject: "New lead received: " + lead.name,
    body: [
      "New lead received",
      "",
      "Name: " + lead.name,
      "Email: " + lead.email,
      "Phone: " + lead.phone,
      "Interest level: " + lead.interest,
      "Lead source: " + lead.source,
      "",
      "Notes: " + lead.notes,
    ].join("\n"),
  };
}

function slackLeadText(lead) {
  return leadMessage(lead, false).body.replace(
    /[&<>]/g,
    (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[character],
  );
}

const config = {
  channel: "SLACK_CHANNEL_ID",
  admin: "sales-admin@example.invalid",
  sourceProperty: "form_lead_source",
  interestProperty: "form_interest_level",
};
const settings = leadSettings(
  config.channel,
  config.admin,
  config.sourceProperty,
  config.interestProperty,
);
const trigger = $("Watch for new lead rows").params;
const sheetId = String(trigger.sheetName.value).replace(/^gid=/, "");
if (!/^\d+$/.test(sheetId)) throw new Error("Select the Google Sheets tab by numeric ID");
const scope = leadScope(trigger.documentId.value, Number(sheetId));
return uniqueSubmittedLeads($input.all().map((item) => item.json)).map((lead, index) => ({
  json: { lead, settings, scope, slackText: slackLeadText(lead), mail: leadMessage(lead, false) },
  pairedItem: { item: index },
}));

function latestLeadContacts(leads) {
  return [...new Map(leads.map((lead) => [lead.email, lead])).values()];
}

function contactSearch(email) {
  return {
    filterGroups: [{ filters: [{ propertyName: "email", operator: "EQ", value: email }] }],
    properties: ["email"],
    limit: 2,
  };
}

const all = $input.all();
const selected = new Set(
  latestLeadContacts(all.map((item) => item.json.lead)).map((lead) => lead.key),
);
return all.flatMap((item, index) =>
  selected.has(item.json.lead.key)
    ? [
        {
          json: { ...item.json, search: contactSearch(item.json.lead.email) },
          pairedItem: { item: index },
        },
      ]
    : [],
);

