  return ["string", "number", "boolean"].includes(typeof value) ? String(value).trim() : "";
}

function contactTarget(search, lead) {
  if (
    !Array.isArray(search?.results) ||
    search.results.length > 1 ||
    search.paging?.next ||
    search.paging?.nextAfter ||
    (search.total != null && search.total !== search.results.length)
  ) {
    throw new Error("HubSpot did not return a unique contact lookup by email");
  }
  const record = search.results[0];
  if (record === undefined) return null;
  if (
    record.archived === true ||
    !/^\d+$/.test(record.id ?? "") ||
    leadCell(record.properties?.email).toLowerCase() !== lead.email
  ) {
    throw new Error("HubSpot returned a contact for a different email");
  }
  return record.id;
}

function contactProperties(lead, settings) {
  const entries = {
    phone: lead.phone,
    message: lead.notes,
    [settings.sourceProperty]: lead.source,
    [settings.interestProperty]: lead.interest,
  };
  return Object.fromEntries(Object.entries(entries).filter(([, value]) => value));
}

const inputs = $("Select the latest lead per email").all();
const results = $input.all();
if (inputs.length !== results.length)
  throw new Error("HubSpot results do not match the submitted contacts");
const contactIds = new Set();
return results.map(({ json }, index) => {
  const { lead, settings } = inputs[index].json;
  const recordId = contactTarget(json, lead);
  if (recordId && contactIds.has(recordId))
    throw new Error("HubSpot matched two emails to the same contact ID");
  if (recordId) contactIds.add(recordId);
  return {
    json: {
      lead,
      recordId,
      method: recordId ? "PATCH" : "POST",
      url: "https://api.hubapi.com/crm/v3/objects/contacts" + (recordId ? "/" + recordId : ""),
      properties: { email: lead.email, ...contactProperties(lead, settings) },
    },
    pairedItem: { item: index },
  };
});

