function checkContact(record, lead, selectedId) {
  if (
    !record ||
    !/^\d+$/.test(record.id ?? "") ||
    (selectedId && selectedId !== record.id) ||
    leadCell(record.properties?.email).toLowerCase() !== lead.email
  ) {
    throw new Error("HubSpot did not confirm the expected contact");
  }
  return record.id;
}

const planned = $("Verify the HubSpot contact identity").all();
const receipts = $input.all();
if (planned.length !== receipts.length)
  throw new Error("HubSpot returned an incomplete set of write receipts");
return receipts.map(({ json }, index) => ({
  json: { id: checkContact(json, planned[index].json.lead, planned[index].json.recordId) },
  pairedItem: { item: index },
}));

function sheetLookup(scope) {
  return {
    spreadsheetId: scope.spreadsheetId,
    dataFilters: [
      {
        gridRange: {
          sheetId: scope.sheetId,
          startRowIndex: 0,
          startColumnIndex: 0,
          endColumnIndex: 26,
        },
      },
    ],
    majorDimension: "ROWS",
    valueRenderOption: "FORMATTED_VALUE",
  };
}

const items = $input.all();
const { scope, settings } = items[0].json;
const lookup = sheetLookup(scope);
const { spreadsheetId, ...body } = lookup;
return [
  {
    json: {
      scope,
      settings,
      submitted: items.map((item) => item.json.lead),
      body,
      url:
        "https://sheets.googleapis.com/v4/spreadsheets/" +
        spreadsheetId +
        "/values:batchGetByDataFilter",
    },
  },
];

