function pendingLeadReminders(snapshot, scope, submitted) {
  const [matched] = snapshot?.valueRanges ?? [];
  if (
    snapshot?.spreadsheetId !== scope.spreadsheetId ||
    snapshot.valueRanges.length !== 1 ||
    !matched?.dataFilters?.some((filter) => filter.gridRange?.sheetId === scope.sheetId) ||
    matched.valueRange?.majorDimension !== "ROWS" ||
    !Array.isArray(matched.valueRange.values)
  ) {
    throw new Error("Google Sheets did not confirm the configured response tab");
  }
  const [header, ...rows] = matched.valueRange.values;
  if (!Array.isArray(header)) throw new Error("The response tab needs its header row");
  const titles = header.map(leadCell);
  const names = titles.filter(Boolean);
  const required = ["Timestamp", "E-Mail", "Name Surname", "Interest Level", "Followed Up?"];
  if (new Set(names).size !== names.length || required.some((name) => !names.includes(name))) {
    throw new Error("The response tab is missing a required column or contains duplicate headers");
  }
  const wanted = new Set(submitted.map((lead) => lead.key));
  const matches = new Map();
  for (const cells of rows) {
    const row = Object.fromEntries(
      titles.flatMap((name, index) => (name ? [[name, cells[index] ?? ""]] : [])),
    );
    const identity = leadIdentity(row, leadHeaders(row));
    if (!identity || !wanted.has(identity.key)) continue;
    if (matches.has(identity.key))
      throw new Error("A follow-up row matches more than one Timestamp and E-Mail");
    matches.set(identity.key, row);
  }
  const reminders = [];
  for (const previous of submitted) {
    const row = matches.get(previous.key);
    if (
      !row ||
      leadCell(row["Followed Up?"]) ||
      leadCell(row["Interest Level"]).toLowerCase() !== "hot"
    )
      continue;
    reminders.push(leadFromRow(row));
  }
  return reminders;
}

