    ].join("\n"),
  };
}

const { scope, submitted, settings } = $("Prepare the delayed lookup").first().json;
return pendingLeadReminders($input.first().json, scope, submitted).map((lead) => ({
  json: { lead, settings, mail: leadMessage(lead, true) },
}));
